cd /tmp && cat > verify_login.js <<'EOF'
const fs = require('fs');
const src = fs.readFileSync(process.argv[2], 'utf8');
const vals = {}; let handler;
const document = { getElementById: id => id === 'login-form'
  ? { addEventListener: (_, h) => { handler = h; } }
  : { get value() { return vals[id] ?? ''; } } };
new Function('document', src)(document);
const submit = v => { Object.assign(vals, v); handler({ preventDefault() {} }); };
console.log('--- filled'); submit({ username: 'alice', password: 'pw', 'user-id': 'u-42' });
console.log('--- missing userId'); submit({ 'user-id': '' });
EOF
